LEGACY_RECORDS = [{'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/customer_demand.csv', 'values': {'customer': 'D1', 'demand': '428'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/customer_demand.csv', 'values': {'customer': 'D2', 'demand': '217'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/customer_demand.csv', 'values': {'customer': 'D3', 'demand': '214'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/customer_demand.csv', 'values': {'customer': 'D4', 'demand': '380'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/customer_demand.csv', 'values': {'customer': 'D5', 'demand': '254'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/supply_capacity.csv', 'values': {'region': 'S1', 'supply_capacity': '428'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/supply_capacity.csv', 'values': {'region': 'S2', 'supply_capacity': '217'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/supply_capacity.csv', 'values': {'region': 'S3', 'supply_capacity': '214'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/supply_capacity.csv', 'values': {'region': 'S4', 'supply_capacity': '380'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/supply_capacity.csv', 'values': {'region': 'S5', 'supply_capacity': '254'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/transportation_costs.csv', 'values': {'Unnamed: 0': 'S1', 'D1': '269.3910588020795', 'D2': '1.4537335390933939', 'D3': '99.60345345756605', 'D4': '26.64078166309837', 'D5': '9.537688956880922'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/transportation_costs.csv', 'values': {'Unnamed: 0': 'S2', 'D1': '9.291846876785183', 'D2': '10.874778437070223', 'D3': '144.52609291614627', 'D4': '11.420133077898234', 'D5': '153.1756819927813'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/transportation_costs.csv', 'values': {'Unnamed: 0': 'S3', 'D1': '9.674584301671008', 'D2': '2.6191650959687944', 'D3': '100.8242249168735', 'D4': '3.2121910887916876', 'D5': '133.8493396124168'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/transportation_costs.csv', 'values': {'Unnamed: 0': 'S4', 'D1': '270.57498480010247', 'D2': '32.50253586', 'D3': '4.6842098096469815', 'D4': '1.5682269686546804', 'D5': '9.58927599'}}, {'source': '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/TP_testing/TP7/transportation_costs.csv', 'values': {'Unnamed: 0': 'S5', 'D1': '226.0331910675782', 'D2': '8.669161980826471', 'D3': '65.47681316968448', 'D4': '9.068765258459958', 'D5': '202.65015316425533'}}]
import gurobipy as gp
from gurobipy import GRB
warehouses = []
stores = []
demand = {}
supply_capacity = {}
cost = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('customer_demand.csv'):
        store = rec['values']['customer']
        if store not in stores:
            stores.append(store)
        demand[store] = float(rec['values']['demand'])
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('supply_capacity.csv'):
        warehouse = rec['values']['region']
        if warehouse not in warehouses:
            warehouses.append(warehouse)
        supply_capacity[warehouse] = float(rec['values']['supply_capacity'])
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('transportation_costs.csv'):
        warehouse = rec['values']['Unnamed: 0']
        if warehouse not in cost:
            cost[warehouse] = {}
        for store in stores:
            if store not in rec['values']:
                raise ValueError(f'Missing cost for warehouse {warehouse}, store {store}')
            cost[warehouse][store] = float(rec['values'][store])
if set(demand.keys()) != set(stores):
    raise ValueError('Mismatch in store demand keys and store list')
if set(supply_capacity.keys()) != set(warehouses):
    raise ValueError('Mismatch in warehouse supply keys and warehouse list')
for i in warehouses:
    if i not in cost:
        raise ValueError(f'Missing cost row for warehouse {i}')
    for j in stores:
        if j not in cost[i]:
            raise ValueError(f'Missing cost for warehouse {i}, store {j}')
m = gp.Model('GreenMart_Transportation')
x_vars = m.addVars(warehouses, stores, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((cost[i][j] * x_vars[i, j] for i in warehouses for j in stores)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in warehouses)) == demand[j] for j in stores), name='')
m.addConstrs((gp.quicksum((x_vars[i, j] for j in stores)) <= supply_capacity[i] for i in warehouses), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')